import { appendFileSync, existsSync, readFileSync } from "node:fs";
import { data, extension, resource, tag } from "@tinker/core";
import type { Namespace, Resource, Scope, Tag } from "@tinker/core";
import type { Tinkerer } from "./index.ts";

export declare namespace Persistence {
  export type Handle = {
    readonly file: Tag.Handle<string>;
    /** Resolve before a direct read or update in a namespace that has not run yet.
     * Setup restores messages and owns one watch until the session closes. */
    readonly transcript: Resource.Handle<void>;
    readonly extension: Scope.Extension;
  };
}

/** Read a JSONL transcript file into messages: one message per non-empty line. A missing file
 * reads as an empty transcript. The file is our own, written by {@link persist}. */
export function restore(file: string): readonly Tinkerer.Message[] {
  if (!existsSync(file)) return [];
  return readFileSync(file, "utf8")
    .split("\n")
    .filter((line) => line.length > 0)
    .map((line) => JSON.parse(line) as Tinkerer.Message);
}

/** Persist one coder's transcript in a JSONL file. Set `ns` when several coders share a
 * frame and a session; each coder needs its own file. Without `ns`, use the session's ambient
 * namespace. Watching on the session's handle sees that session's writes (ADR 0053). */
export function persist(config: {
  readonly frame: Pick<Tinkerer.Frame, "messages">;
  readonly file: string;
  readonly ns?: Namespace;
}): Scope.Extension {
  const { transcript } = declareTranscript(config);
  return extension({
    label: "tinkerer.persist",
    hooks: {
      session(event) {
        event.resolve(transcript, config.ns === undefined ? undefined : { ns: config.ns });
        return event.next();
      },
    },
  });
}

/** Declare one persistence graph. Namespace tags choose each file; a namespace without a
 * file does not save messages. Sessions, runs, and direct writes prepare their own transcript.
 * Reads do not prepare it: resolve `transcript` before a direct read or update in a namespace
 * that has not been prepared. A direct set still replaces the whole message list. */
export function persistence(config: {
  readonly frame: Pick<Tinkerer.Frame, "messages">;
}): Persistence.Handle {
  const { file, transcript, restoring } = declareTranscript(config);
  return {
    file,
    transcript,
    extension: extension({
      label: "tinkerer.persistence",
      hooks: {
        session(event) {
          event.resolve(transcript);
          return event.next();
        },
        run(event) {
          event.resolve(transcript);
          return event.next();
        },
        write(event) {
          if (event.cell === config.frame.messages && !event.resolve(restoring)) {
            event.resolve(transcript);
          }
          return event.next();
        },
      },
    }),
  };
}

function declareTranscript(config: {
  readonly frame: Pick<Tinkerer.Frame, "messages">;
  readonly file?: string;
}) {
  const file = tag<string>({ label: "tinkerer.persist.file" });
  const restoring = data({ label: "tinkerer.persist.restoring", initial: false });
  const transcript = resource({
    label: "tinkerer.persist.transcript",
    target: "session",
    depends: {
      messages: config.frame.messages.controller,
      file: file.optional,
      restoring: restoring.controller,
    },
    factory: ({ messages, file, restoring }, ctx) => {
      const path = file.present ? file.value : config.file;
      if (path === undefined) return;
      const seeded = restore(path);
      if (seeded.length > 0) {
        restoring.set(true);
        try {
          messages.set(seeded);
        } finally {
          restoring.set(false);
        }
      }
      let written = seeded.length;
      const stop = messages.watch((list) => {
        for (const message of list.slice(written)) {
          appendFileSync(path, `${JSON.stringify(message)}\n`);
        }
        written = list.length;
      });
      ctx.defer(stop);
    },
  });
  return { file, transcript, restoring };
}

import { HttpResponse } from "../http/index.ts";

/** The caller owns the stream until its reader closes, including a pending `next()` on abort. */
export async function consumeStep(
  events: AsyncIterable<HttpResponse.SseEvent>,
  onEvent: (event: HttpResponse.SseEvent) => void,
  signal: AbortSignal,
): Promise<void> {
  const iterator = events[Symbol.asyncIterator]();
  let wake: () => void = () => undefined;
  const stopped = new Promise<undefined>((resolve) => {
    wake = () => resolve(undefined);
  });
  signal.addEventListener("abort", wake, { once: true });
  try {
    for (;;) {
      signal.throwIfAborted();
      const next = await Promise.race([iterator.next(), stopped]);
      signal.throwIfAborted();
      if (next === undefined || next.done) return;
      onEvent(next.value);
    }
  } finally {
    signal.removeEventListener("abort", wake);
    await iterator.return?.();
  }
}

/** Own the response reader so `return()` can cancel a pending read before the SSE generator
 * reaches its next yield. The returned iterator belongs to the turn that consumes the step. */
export function readStepEvents(
  response: HttpResponse.Handle,
): AsyncIterable<HttpResponse.SseEvent> {
  return new StepEvents(response);
}

class StepEvents implements AsyncIterableIterator<HttpResponse.SseEvent> {
  private reader: ReadableStreamDefaultReader<Uint8Array>;
  private events: AsyncIterator<HttpResponse.SseEvent>;
  private closing?: Promise<void>;

  constructor(response: HttpResponse.Handle) {
    this.reader = response.stream().getReader();
    const body = new ReadableStream<Uint8Array>(
      { pull: (controller) => this.pull(controller), cancel: () => this.close() },
      { highWaterMark: 0 },
    );
    this.events = HttpResponse.make(response.request, {
      status: response.status,
      headers: response.headers,
      body,
    })
      .sse()
      [Symbol.asyncIterator]();
  }

  [Symbol.asyncIterator](): AsyncIterableIterator<HttpResponse.SseEvent> {
    return this;
  }

  async next(): Promise<IteratorResult<HttpResponse.SseEvent>> {
    try {
      const next = await this.events.next();
      if (next.done) await this.close();
      return next;
    } catch (error) {
      await this.close();
      throw error;
    }
  }

  async return(): Promise<IteratorResult<HttpResponse.SseEvent>> {
    await this.close();
    return this.events.return?.() ?? { done: true, value: undefined };
  }

  private async pull(controller: ReadableStreamDefaultController<Uint8Array>): Promise<void> {
    const next = await this.reader.read();
    if (next.done) controller.close();
    else controller.enqueue(next.value);
  }

  private close(): Promise<void> {
    return (this.closing ??= this.cancel());
  }

  private async cancel(): Promise<void> {
    try {
      await this.reader.cancel();
    } finally {
      this.reader.releaseLock();
    }
  }
}

import { spawn } from "node:child_process";
import { operation } from "@tinker/core";
import type { Operation } from "@tinker/core";
import { z } from "zod";
import { cwd } from "./read.ts";

export const bashDescription =
  "Run a bash command in cwd; answers its combined output and exit code";

export const bashInput = {
  command: z.string().min(1),
  timeout: z.number().int().positive().optional(),
};

export type BashInput = {
  readonly command: string;
  readonly timeout?: number;
};

const bashSchema = z.object(bashInput);

/** The default wait before a command is killed, in milliseconds. */
const defaultTimeout = 30_000;

/** The most output kept, in characters; the head is dropped, the tail stays. */
const outputCap = 20_000;

/** The shipped `bash` tool: `{ command, timeout? }` → `bash -c command` in cwd, stdout and
 * stderr merged in arrival order, then `[exit <code>]` when non-zero, `[timed out after <ms> ms]`
 * when the timeout killed it. A forced close kills it through the signal. */
export const bash: Operation.Handle<Promise<string>, BashInput> = operation({
  label: "bash",
  input: (raw: unknown): BashInput => bashSchema.parse(raw),
  depends: { cwd: cwd.required },
  run: (deps, ctx) => runCommand(deps.cwd, ctx.input, ctx.signal),
});

type Ended = { readonly code: number | null; readonly timedOut: boolean };

function runCommand(base: string, input: BashInput, signal: AbortSignal): Promise<string> {
  const timeout = input.timeout ?? defaultTimeout;
  const child = spawn("bash", ["-c", input.command], {
    cwd: base,
    stdio: ["ignore", "pipe", "pipe"],
    signal,
  });
  const chunks: string[] = [];
  child.stdout.on("data", (chunk: Buffer) => chunks.push(chunk.toString("utf8")));
  child.stderr.on("data", (chunk: Buffer) => chunks.push(chunk.toString("utf8")));
  return new Promise<string>((resolve, reject) => {
    let timedOut = false;
    const timer = setTimeout(() => {
      timedOut = true;
      child.kill("SIGKILL");
    }, timeout);
    child.on("error", (error) => {
      clearTimeout(timer);
      reject(error);
    });
    child.on("close", (code) => {
      clearTimeout(timer);
      resolve(readOutcome(chunks.join(""), { code, timedOut }, timeout));
    });
  });
}

function readOutcome(output: string, ended: Ended, timeout: number): string {
  const kept = output.length > outputCap ? `…${output.slice(-outputCap)}` : output;
  if (ended.timedOut) return `${kept}\n[timed out after ${timeout} ms]`;
  if (ended.code !== 0) return `${kept}\n[exit ${ended.code ?? "signal"}]`;
  return kept;
}

import { readFile, writeFile } from "node:fs/promises";
import { operation } from "@tinker/core";
import type { Operation } from "@tinker/core";
import { z } from "zod";
import type { Errors } from "../errors.ts";
import { cwd } from "./read.ts";
import { resolveUnder } from "./path.ts";

export const editDescription =
  "Replace one exact occurrence of oldText by newText in a file under cwd";

export const editInput = {
  path: z.string(),
  oldText: z.string().min(1),
  newText: z.string(),
};

export type EditInput = {
  readonly path: string;
  readonly oldText: string;
  readonly newText: string;
};

const editSchema = z.object(editInput);

/** The shipped `edit` tool: `{ path, oldText, newText }` → the one exact match replaced; zero
 * or several matches refuse with `EditMiss { path, count }` so the model narrows `oldText`. */
export const edit: Operation.Handle<Promise<string>, EditInput> = operation({
  label: "edit",
  input: (raw: unknown): EditInput => editSchema.parse(raw),
  depends: { cwd: cwd.required },
  run: async ({ cwd }, ctx) => {
    const target = resolveUnder(cwd, ctx.input.path, "edit");
    const text = await readFile(target, "utf8");
    const count = countMatches(text, ctx.input.oldText);
    if (count !== 1)
      ctx.raise("EditMiss", {
        label: "edit",
        path: ctx.input.path,
        count,
      } satisfies Errors.Payload<"EditMiss">);
    await writeFile(
      target,
      text.replace(ctx.input.oldText, () => ctx.input.newText),
      "utf8",
    );
    return `Edited ${ctx.input.path}`;
  },
});

function countMatches(text: string, needle: string): number {
  let count = 0;
  for (let at = text.indexOf(needle); at !== -1; at = text.indexOf(needle, at + needle.length))
    count += 1;
  return count;
}

import { relative, resolve, sep } from "node:path";
import { raise } from "../errors.ts";

/** Resolve `path` against `base` and refuse a result outside it (`PathOutsideCwd`). The one
 * guard every shipped tool takes before it touches the disk. */
export function resolveUnder(base: string, path: string, label: string): string {
  const target = resolve(base, path);
  const rel = relative(base, target);
  if (rel === ".." || rel.startsWith(`..${sep}`)) raise("PathOutsideCwd", { label, path });
  return target;
}

import { readFile } from "node:fs/promises";
import { operation, tag } from "@tinker/core";
import type { Operation, Tag } from "@tinker/core";
import { z } from "zod";
import { resolveUnder } from "./path.ts";

export const cwd: Tag.Handle<string> = tag({ label: "tinkerer.cwd" });

export const readDescription = "Read a file under cwd, optionally a window of lines";

export const readInput = {
  path: z.string(),
  offset: z.number().int().min(0).optional(),
  limit: z.number().int().positive().optional(),
};

export type ReadInput = {
  readonly path: string;
  readonly offset?: number;
  readonly limit?: number;
};

const readSchema = z.object(readInput);

export const read: Operation.Handle<Promise<string>, ReadInput> = operation({
  label: "read",
  input: readRawInput,
  depends: { cwd: cwd.required },
  run: async ({ cwd }, ctx) => {
    const target = resolveUnder(cwd, ctx.input.path, "read");
    const text = await readFile(target, "utf8");
    return windowLines(text, ctx.input.offset ?? 0, ctx.input.limit);
  },
});

function readRawInput(raw: unknown): ReadInput {
  return readSchema.parse(raw);
}

function windowLines(text: string, offset: number, limit: number | undefined): string {
  const lines = text.split("\n");
  const end = limit === undefined ? lines.length : offset + limit;
  return lines.slice(offset, end).join("\n");
}

import { mkdir, writeFile } from "node:fs/promises";
import { dirname } from "node:path";
import { operation } from "@tinker/core";
import type { Operation } from "@tinker/core";
import { z } from "zod";
import { cwd } from "./read.ts";
import { resolveUnder } from "./path.ts";

export const writeDescription = "Write a whole file under cwd, creating parent folders";

export const writeInput = {
  path: z.string(),
  content: z.string(),
};

export type WriteInput = {
  readonly path: string;
  readonly content: string;
};

const writeSchema = z.object(writeInput);

export const write: Operation.Handle<Promise<string>, WriteInput> = operation({
  label: "write",
  input: (raw: unknown): WriteInput => writeSchema.parse(raw),
  depends: { cwd: cwd.required },
  run: async ({ cwd }, ctx) => {
    const target = resolveUnder(cwd, ctx.input.path, "write");
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, ctx.input.content, "utf8");
    return `Wrote ${Buffer.byteLength(ctx.input.content, "utf8")} bytes to ${ctx.input.path}`;
  },
});
